def main():
    files=[f for f in (sys.argv[1:] or glob.glob("npidata_pfile_*.csv")) if "fileheader" not in f]
    if not files:
        print("ERROR: no npidata_pfile_*.csv found next to this script."); return
    path=files[0]; print(f"Reading {path} for {len(NPIS)} NPIs ...")
    with open(path, newline="", encoding="utf-8", errors="replace") as fh:
        rd=csv.reader(fh); header=next(rd)
        idx={name:i for i,name in enumerate(header)}
        NPI=idx["NPI"]; ENUM=idx["Provider Enumeration Date"]; SEX=idx["Provider Sex Code"]
        CRED=idx["Provider Credential Text"]
        tax=[(idx[f"Healthcare Provider Taxonomy Code_{k}"], idx[f"Healthcare Provider Primary Taxonomy Switch_{k}"]) for k in range(1,16)]
        out=[]; n=0
        for r in rd:
            n+=1
            if n % 1000000 == 0: print(f"  ...{n:,} rows scanned")
            npi=r[NPI].strip()
            if npi not in NPIS: continue
            prim=""; secs=[]
            for ci,si in tax:
                code=r[ci].strip()
                if not code: continue
                if r[si].strip().upper()=="Y" and not prim: prim=code
                else: secs.append(code)
            if not prim and secs: prim=secs.pop(0)
            out.append([npi, r[ENUM], r[SEX].strip(), r[CRED].strip(), prim, ";".join(secs)])
        print(f"Scanned {n:,} rows; matched {len(out)} of {len(NPIS)} NPIs.")
    with open("nppes_lookup.csv","w",newline="",encoding="utf-8-sig") as fh:
        w=csv.writer(fh); w.writerow(["npi","enumeration_date","sex","credential","primary_taxonomy","secondary_taxonomies"])
        w.writerows(out)
    print("DONE -> nppes_lookup.csv  (upload this)")

main()
